update modules set description = 'Train your eyes to constantly scan the room for dead soldiers, raised hands, and the lost look on a guest''s face, so you see the problem before the guest says a word.' where id = 23;
update modules set description = 'Expert bartenders move less, not faster. This teaches two-handed service (grabbing the glass with one hand while hitting the gun with the other) to cut dead time from every movement.' where id = 27;
update modules set description = 'The rush isn''t over when the tickets stop. This teaches the 3-minute reload: replenishing citrus, ice, and glassware in the short gaps between waves.' where id = 28;
update modules set description = 'Being in the weed is hospitality''s term for overwhelmed. This is the psychological module: acknowledge every guest, work tickets in order, and remember that slow is smooth and smooth is fast.' where id = 30;
update modules set description = 'A technical breakdown of the two-step lever system, cutting the foil below the lip, and the silent extraction of the cork, so no one ever struggles with a bottle in front of a guest.' where id = 32;
